-- Resources content for the Programs and Clocks merge in Log (CLAUDE.md,
-- "Resources stay in step with the code"): Programs is the one entry point and
-- the Clocks tab is gone, so the two guides that described those screens are
-- updated and one release note is added. Content only — no schema.

select private.rc_release_guide(
  p_slug => 'log-read-a-clock',
  p_tool_key => 'log',
  p_title => 'Read a clock',
  p_summary => 'What the ring diagram shows, who uses the clock, and its versions.',
  p_screen_keys => array['log.clock'],
  p_sort_order => 10,
  p_version_note => 'Updated for Programs and Clocks',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a clock from the program that airs on it: on the program's page, select "},{"type":"text","text":"Open clock","marks":[{"type":"bold"}]},{"type":"text","text":". A clock's page draws each version of the clock as a ring, the same way the network's own clock diagrams do, with a table of the same slots beside it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reading the ring"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The inner ring is the network's structure: segments, newscasts, billboards, and breaks, each at its minute in the hour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The outer ring marks the station's local opportunities — the slots WUWF may fill."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Minute labels at each boundary are rotated along the radius so close boundaries stay readable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A floating break is drawn across its whole window with a hatched fill and a dashed border. Its exact position within that window is the station's call."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hover over a segment to see its label and times."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Who uses this clock"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Used by","marks":[{"type":"bold"}]},{"type":"text","text":" panel lists every program scheduled on the clock, with its days and air time. Select a program's name to open it. Most clocks belong to one program; the placeholder clock is shared by every program still waiting for a network clock."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Versions","marks":[{"type":"bold"}]},{"type":"text","text":" panel lists each version and marks the one in effect now. A version can't be edited once it exists — a correction is a new version, started with "},{"type":"text","text":"+ New version","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Producers can put another program on this clock with "},{"type":"text","text":"Schedule a program with this clock","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-schedule-a-program',
  p_tool_key => 'log',
  p_title => 'Schedule a program',
  p_summary => 'Put a program on the air, choose its clock, and find programs that still need one.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 20,
  p_version_note => 'Updated for Programs and Clocks',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs is where every clock is reached from: the list shows each program's air time, its clock, and whether it still needs one. Scheduling and changing a clock are producer tasks."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find what needs attention"}]},{"type":"paragraph","content":[{"type":"text","text":"Use the filters above the list. "},{"type":"text","text":"Needs a clock","marks":[{"type":"bold"}]},{"type":"text","text":" shows the programs still on the shared placeholder clock, and "},{"type":"text","text":"Not scheduled","marks":[{"type":"bold"}]},{"type":"text","text":" shows programs with no current schedule. Clocks no program uses are listed under "},{"type":"text","text":"Unused clocks","marks":[{"type":"bold"}]},{"type":"text","text":" below the list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Schedule a program"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Programs","marks":[{"type":"bold"}]},{"type":"text","text":" in Log and select the program."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ Schedule","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the clock template the program runs on, and the entry type: recurring, override, or holiday. If the clock doesn't exist yet, select "},{"type":"text","text":"Create a clock for this program","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a recurring entry, pick the days of the week."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter the start date, and an end date if the entry stops."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter the air time and the duration in minutes, then save."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change a clock or an entry"}]},{"type":"paragraph","content":[{"type":"text","text":"On a program's page, select "},{"type":"text","text":"Change clock","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Edit entry","marks":[{"type":"bold"}]},{"type":"text","text":" beside the schedule entry. Rundowns that were already generated keep the clock they were built from; the new clock applies to rundowns generated from then on."}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Edit program","marks":[{"type":"bold"}]},{"type":"text","text":" in the Details panel to change a program's name, kind, or description."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-29-log-programs-and-clocks',
  p_tool_key => 'log',
  p_released_on => '2026-09-29',
  p_title => 'Programs and clocks in one place',
  p_guide_slugs => array['log-schedule-a-program', 'log-read-a-clock'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs is now the one place to start. The list shows each program's air time, days, and clock, with filters for programs that still need a clock. A program's page shows the clock behind each schedule entry and lets producers change it, and a clock's page lists every program that uses it. The separate Clocks tab is gone."}]}]}$body$
);
